from operator import eq, ne, lt, le, gt, ge

_CMP = {"=": eq, "!=": ne, "<": lt, "<=": le, ">": gt, ">=": ge}


def _agg_name(func, arg):
    return "%s(%s)" % (func, arg)


def _and3(a, b):
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def _or3(a, b):
    if a is True or b is True:
        return True
    if a is None or b is None:
        return None
    return False


def _not3(a):
    if a is None:
        return None
    return not a


def _compile_operand(opnd, mode):
    """mode 'row': ctx is a row dict. mode 'group': ctx is (group_cols, agg_values)."""
    kind = opnd[0]
    if kind == "val":
        v = opnd[1]
        return lambda ctx: v
    if kind == "col":
        name = opnd[1]
        if mode == "row":
            return lambda ctx: ctx[name]
        return lambda ctx: ctx[0][name]
    if kind == "agg":
        name = _agg_name(opnd[1], opnd[2])
        return lambda ctx: ctx[1][name]
    raise ValueError("bad operand: %r" % (opnd,))


def _compile_cond(cond, mode):
    op = cond[0]
    if op in _CMP:
        fn = _CMP[op]
        a = _compile_operand(cond[1], mode)
        b = _compile_operand(cond[2], mode)

        def cmp_(ctx):
            x = a(ctx)
            y = b(ctx)
            if x is None or y is None:
                return None
            return bool(fn(x, y))
        return cmp_
    if op == "and":
        c1 = _compile_cond(cond[1], mode)
        c2 = _compile_cond(cond[2], mode)
        return lambda ctx: _and3(c1(ctx), c2(ctx))
    if op == "or":
        c1 = _compile_cond(cond[1], mode)
        c2 = _compile_cond(cond[2], mode)
        return lambda ctx: _or3(c1(ctx), c2(ctx))
    if op == "not":
        c = _compile_cond(cond[1], mode)
        return lambda ctx: _not3(c(ctx))
    if op == "is_null":
        a = _compile_operand(cond[1], mode)
        return lambda ctx: a(ctx) is None
    if op == "in":
        a = _compile_operand(cond[1], mode)
        lst = list(cond[2])
        if not lst:
            return lambda ctx: False
        has_null = any(v is None for v in lst)
        nonnull = [v for v in lst if v is not None]
        try:
            nonnull_set = set(nonnull)
        except TypeError:
            nonnull_set = None

        def in_(ctx):
            x = a(ctx)
            if x is None:
                return None
            if nonnull_set is not None:
                found = x in nonnull_set
            else:
                found = any(x == v for v in nonnull)
            if found:
                return True
            return None if has_null else False
        return in_
    if op == "between":
        a = _compile_operand(cond[1], mode)
        lo = cond[2]
        hi = cond[3]

        def between_(ctx):
            x = a(ctx)
            if x is None:
                r1 = None
                r2 = None
            else:
                r1 = None if lo is None else (x >= lo)
                r2 = None if hi is None else (x <= hi)
            return _and3(r1, r2)
        return between_
    raise ValueError("bad condition: %r" % (cond,))


def _collect_aggs(cond, out):
    """Collect (func, arg) aggregates referenced in a having condition."""
    op = cond[0]

    def opnd(o):
        if o[0] == "agg":
            out.append((o[1], o[2]))

    if op in _CMP:
        opnd(cond[1])
        opnd(cond[2])
    elif op in ("and", "or"):
        _collect_aggs(cond[1], out)
        _collect_aggs(cond[2], out)
    elif op == "not":
        _collect_aggs(cond[1], out)
    elif op in ("is_null", "in", "between"):
        opnd(cond[1])


def _compute_agg(func, arg, grows):
    if func == "count" and arg == "*":
        return len(grows)
    vals = [r[arg] for r in grows if r[arg] is not None]
    if func == "count":
        return len(vals)
    if func == "count_distinct":
        return len(set(vals))
    if not vals:
        return None
    if func == "sum":
        return sum(vals)
    if func == "min":
        return min(vals)
    if func == "max":
        return max(vals)
    if func == "avg":
        return sum(vals) // len(vals)
    raise ValueError("bad aggregate: %r" % (func,))


def run_query(rows, query):
    select = query["select"]
    where = query.get("where")
    group_by = list(query.get("group_by") or [])
    having = query.get("having")

    # Parse select items.
    items = []  # (outkey, is_agg, payload)
    has_agg = False
    for it in select:
        if isinstance(it, str):
            items.append((it, False, it))
        else:
            func, arg = it[0], it[1]
            items.append((_agg_name(func, arg), True, (func, arg)))
            has_agg = True

    # WHERE
    if where is not None:
        wf = _compile_cond(where, "row")
        filtered = [r for r in rows if wf(r) is True]
    else:
        filtered = list(rows)

    out = []
    if group_by or has_agg:
        # Grouping (hash-based, insertion order = first appearance)
        if group_by:
            groups = {}
            if len(group_by) == 1:
                g0 = group_by[0]
                for r in filtered:
                    k = (r[g0],)
                    lst = groups.get(k)
                    if lst is None:
                        groups[k] = [r]
                    else:
                        lst.append(r)
            else:
                for r in filtered:
                    k = tuple(r[c] for c in group_by)
                    lst = groups.get(k)
                    if lst is None:
                        groups[k] = [r]
                    else:
                        lst.append(r)
        else:
            groups = {(): filtered}

        # Aggregates needed
        needed = []
        for key, is_agg, payload in items:
            if is_agg:
                needed.append(payload)
        if having is not None:
            _collect_aggs(having, needed)
        agg_specs = {}
        for func, arg in needed:
            name = _agg_name(func, arg)
            if name not in agg_specs:
                agg_specs[name] = (func, arg)

        hf = _compile_cond(having, "group") if having is not None else None

        for k, grows in groups.items():
            gcols = dict(zip(group_by, k))
            aggvals = {name: _compute_agg(f, a, grows)
                       for name, (f, a) in agg_specs.items()}
            if hf is not None and hf((gcols, aggvals)) is not True:
                continue
            orow = {}
            for key, is_agg, payload in items:
                if is_agg:
                    orow[key] = aggvals[key]
                else:
                    orow[key] = gcols[payload]
            out.append(orow)
    else:
        cols = [payload for _, _, payload in items]
        for r in filtered:
            out.append({c: r[c] for c in cols})

    # DISTINCT
    if query.get("distinct"):
        seen = set()
        uniq = []
        for orow in out:
            k = tuple(orow.values())
            if k not in seen:
                seen.add(k)
                uniq.append(orow)
        out = uniq

    # ORDER BY (stable, applied from last key to first)
    order_by = query.get("order_by") or []
    for entry in reversed(order_by):
        key, direction, nulls = entry[0], entry[1], entry[2]
        desc = (direction == "desc")
        if nulls is None:
            nulls_first = not desc
        else:
            nulls_first = (nulls == "first")
        nonnull = [r for r in out if r[key] is not None]
        nullrows = [r for r in out if r[key] is None]
        nonnull.sort(key=lambda r: r[key], reverse=desc)  # stable even with reverse
        out = nullrows + nonnull if nulls_first else nonnull + nullrows

    # OFFSET / LIMIT
    offset = query.get("offset")
    limit = query.get("limit")
    if offset:
        out = out[offset:]
    if limit is not None:
        out = out[:limit]
    return out
